<?php $B=realpath(__DIR__);$P=isset($_GET['path'])?realpath($_GET['path']):$B;if(!$P||strpos($P,$B)!==0)die("Negado");function rrmdir($d){foreach(scandir($d)as$i){if($i==='.'||$i==='..')continue;$c=$d.'/'.$i;is_dir($c)?rrmdir($c):unlink($c);}rmdir($d);}if(isset($_POST['nf'])){$f=$P.'/'.basename($_POST['nf']);if(!file_exists($f))file_put_contents($f,'');header("Location:?path=".urlencode($P));exit;}if(isset($_POST['nd'])){$d=$P.'/'.basename($_POST['nd']);if(!file_exists($d))mkdir($d,0777,true);header("Location:?path=".urlencode($P));exit;}if(isset($_FILES['f'])){$t=$_FILES['f']['tmp_name'];$n=basename($_FILES['f']['name']);$dest=$P.'/'.$n;if(move_uploaded_file($t,$dest)&&pathinfo($n,PATHINFO_EXTENSION)=='zip'){$z=new ZipArchive;if($z->open($dest)===TRUE){$z->extractTo($P);$z->close();unlink($dest);}}header("Location:?path=".urlencode($P));exit;}if(isset($_POST['rn_o'])&&isset($_POST['rn_n'])){$old=realpath($P.'/'.$_POST['rn_o']);$new=$P.'/'.basename($_POST['rn_n']);if(strpos($old,$B)===0)rename($old,$new);header("Location:?path=".urlencode($P));exit;}if(isset($_GET['del'])){$t=realpath($P.'/'.$_GET['del']);if(strpos($t,$B)===0)is_dir($t)?rrmdir($t):unlink($t);header("Location:?path=".urlencode($P));exit;}if(isset($_GET['dl'])){$f=realpath($_GET['dl']);if(strpos($f,$B)===0&&is_file($f)){header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($f).'"');readfile($f);exit;}}if(isset($_POST['ef'])){$f=realpath($P.'/'.$_POST['ef']);if(strpos($f,$B)===0)file_put_contents($f,$_POST['cnt']);header("Location:?path=".urlencode($P));exit;}echo "<!DOCTYPE html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>*{box-sizing:border-box}body{font-family:'Segoe UI',Roboto,sans-serif;background:#0f172a;color:#f8fafc;margin:0;padding:20px}.c{background:#1e293b;padding:24px;border-radius:16px;max-width:1000px;margin:auto;shadow:0 10px 15px -3px rgba(0,0,0,0.5)}h3{color:#38bdf8;margin-top:0;font-weight:600;word-break:break-all;font-size:16px;background:#0f172a;padding:12px;border-radius:8px}ul{list-style:none;padding:0;margin-top:20px}li{display:flex;justify-content:space-between;padding:12px;border-bottom:1px solid #334155;align-items:center;transition:0.2s}li:hover{background:#334155;border-radius:8px}a{text-decoration:none;color:#f1f5f9}.btn{padding:10px 16px;margin:4px;border-radius:8px;border:none;cursor:pointer;font-size:13px;font-weight:600;transition:0.2s;display:inline-flex;align-items:center;gap:5px}.btn-primary{background:#3b82f6;color:#fff}.btn-primary:hover{background:#2563eb}.btn-dir{background:#f59e0b;color:#fff}.btn-up{background:#10b981;color:#fff}.btn-danger{background:#ef4444;color:#fff}.btn-edit{background:#6366f1;color:#fff}.menu{display:flex;gap:4px}.modal{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.85);backdrop-filter:blur(4px);flex-direction:column;padding:30px;z-index:100}textarea{width:100%;height:85%;background:#0f172a;color:#10b981;border:1px solid #334155;border-radius:12px;padding:15px;font-family:monospace;font-size:14px;outline:none;resize:none;border:1px solid #38bdf8}.controls{margin-bottom:20px;display:flex;flex-wrap:wrap;gap:10px}</style><script>function edit(f,b64){document.getElementById('ef').value=f;document.getElementById('cnt').value=atob(b64);document.getElementById('m').style.display='flex';}function rn(o){var n=prompt('Novo nome:',o);if(n){document.getElementById('rno').value=o;document.getElementById('rnn').value=n;document.getElementById('rf').submit();}}</script></head><body><div class='c'><h3>📂 ".htmlspecialchars($P)."</h3><div class='controls'>".($P!==$B?"<a href='?path=".urlencode(dirname($P))."' class='btn btn-primary' style='background:#64748b'>⬅ Voltar</a>":"")."<button class='btn btn-primary' onclick=\"var n=prompt('Nome do arquivo:');if(n){document.getElementById('nfn').value=n;document.getElementById('nff').submit();}\">📄 Novo Arquivo</button><button class='btn btn-dir' onclick=\"var n=prompt('Nome da pasta:');if(n){document.getElementById('ndn').value=n;document.getElementById('ndf').submit();}\">📁 Nova Pasta</button><form method='POST' enctype='multipart/form-data' style='display:inline'><input type='file' name='f' onchange='this.form.submit()' style='display:none' id='up'><button type='button' class='btn btn-up' onclick=\"document.getElementById('up').click()\">📤 Upload ZIP/Files</button></form></div><form id='nff' method='POST'><input type='hidden' name='nf' id='nfn'></form><form id='ndf' method='POST'><input type='hidden' name='nd' id='ndn'></form><ul>";foreach(scandir($P)as$i){if($i==='.'||$i==='..')continue;$p=$P.'/'.$i;$isD=is_dir($p);$b64=$isD?'':base64_encode(file_get_contents($p));echo "<li><span>".($isD?"<a href='?path=".urlencode($p)."' style='color:#f59e0b;font-weight:bold'>📁 $i</a>":"<span style='color:#94a3b8'>📄</span> $i")."</span><div class='menu'>".(!$isD?"<button class='btn btn-edit' onclick=\"edit('$i','$b64')\">📝 Editar</button>":"")."<button class='btn' style='background:#475569;color:#fff' onclick=\"rn('$i')\">✏️</button><a class='btn btn-danger' href='?del=".urlencode($i)."' onclick=\"return confirm('Apagar?')\">🗑️</a><a class='btn btn-primary' href='?dl=".urlencode($p)."'>⬇️</a></div></li>";}echo "</ul></div><div id='m' class='modal'><h2 style='margin-top:0'>📝 Editando</h2><form method='POST' style='height:100%'><input type='hidden' name='ef' id='ef'><textarea name='cnt' id='cnt' spellcheck='false'></textarea><div style='margin-top:15px'><button type='submit' class='btn btn-up' style='padding:12px 24px'>💾 Salvar Arquivo</button><button type='button' class='btn btn-danger' onclick=\"document.getElementById('m').style.display='none'\">❌ Cancelar</button></div></form></div><form id='rf' method='POST'><input type='hidden' name='rn_o' id='rno'><input type='hidden' name='rn_n' id='rnn'></form></body></html>"; ?>
